B=[
('الرِّحْلَةُ السَّابِعَةُ: رِسَالَةُ الْخَلِيفَةِ','Yedinci yolculuk: Halifenin mektubu',[
('فِي الْيَوْمِ الْأَخِيرِ جَاءَ الْحَمَّالُ مُبَكِّرًا.','Son gün hamal erkenden geldi.'),
('قَالَ السِّنْدِبَادُ: «قُلْتُ بَعْدَ السَّادِسَةِ: لَا أُسَافِرُ أَبَدًا.»','Sindbad dedi ki: “Altıncıdan sonra dedim ki: Bir daha asla yolculuk etmem.”'),
('«لَكِنْ فِي يَوْمٍ جَاءَنِي رَسُولُ الْخَلِيفَةِ، وَقَالَ: الْخَلِيفَةُ يَطْلُبُكَ.»','“Ama bir gün halifenin elçisi geldi ve dedi ki: Halife seni istiyor.”'),
('«قَالَ الْخَلِيفَةُ: يَا سِنْدِبَادُ، أُرِيدُ أَنْ تَحْمِلَ رِسَالَتِي وَهَدِيَّتِي إِلَى مَلِكِ سَرَنْدِيبَ.»','“Halife dedi ki: Ey Sindbad, mektubumu ve hediyemi Serendib kralına götürmeni istiyorum.”'),
('«قُلْتُ: يَا أَمِيرَ الْمُؤْمِنِينَ، أَنَا أَكْرَهُ الْبَحْرَ الْآنَ.»','“Dedim ki: Ey müminlerin emiri, ben artık denizden hoşlanmıyorum.”'),
('«قَالَ: هَذِهِ الْمَرَّةَ فَقَطْ، وَاللّٰهُ يَحْفَظُكَ.»','“Dedi ki: Yalnız bu sefer; Allah seni korur.”'),
('«فَسَمِعْتُ وَأَطَعْتُ، وَخَرَجْتُ إِلَى الْبَصْرَةِ.»','“Dinledim, itaat ettim ve Basra’ya çıktım.”')]),
('الْقَرَاصِنَةُ','Korsanlar',[
('«وَصَلْتُ إِلَى سَرَنْدِيبَ، وَقَدَّمْتُ الْهَدِيَّةَ، فَفَرِحَ الْمَلِكُ كَثِيرًا.»','“Serendib’e vardım ve hediyeyi sundum; kral çok sevindi.”'),
('«ثُمَّ رَكِبْتُ سَفِينَةً لِأَرْجِعَ إِلَى بَلَدِي.»','“Sonra memleketime dönmek için bir gemiye bindim.”'),
('«وَبَعْدَ ثَلَاثَةِ أَيَّامٍ جَاءَتْ سُفُنٌ صَغِيرَةٌ سَرِيعَةٌ.»','“Üç gün sonra küçük, hızlı gemiler geldi.”'),
('«كَانَ فِيهَا قَرَاصِنَةٌ مَعَهُمْ سُيُوفٌ وَرِمَاحٌ.»','“İçlerinde kılıçlı ve mızraklı korsanlar vardı.”'),
('«فَقَتَلُوا بَعْضَ النَّاسِ، وَأَخَذُوا الْبَاقِينَ أَسْرَى.»','“Bazı insanları öldürdüler, geri kalanları esir aldılar.”'),
('«وَبَاعُونَا فِي سُوقِ الْعَبِيدِ فِي جَزِيرَةٍ بَعِيدَةٍ.»','“Bizi uzak bir adada köle pazarında sattılar.”'),
('«فَاشْتَرَانِي رَجُلٌ غَنِيٌّ، وَأَخَذَنِي إِلَى بَيْتِهِ.»','“Beni zengin bir adam satın aldı ve evine götürdü.”')]),
('صَيْدُ الْفِيَلَةِ','Fil avı',[
('«سَأَلَنِي سَيِّدِي: هَلْ تَعْرِفُ الرَّمْيَ بِالسَّهْمِ؟ قُلْتُ: نَعَمْ.»','“Efendim bana sordu: Ok atmayı bilir misin? Dedim ki: Evet.”'),
('«فَأَعْطَانِي قَوْسًا وَسِهَامًا، وَأَخَذَنِي إِلَى غَابَةٍ كَبِيرَةٍ.»','“Bana bir yay ve oklar verdi ve beni büyük bir ormana götürdü.”'),
('«قَالَ: اصْعَدْ هَذِهِ الشَّجَرَةَ، وَإِذَا مَرَّتِ الْفِيَلَةُ فَارْمِهَا.»','“Dedi ki: Bu ağaca çık; filler geçince onlara ok at.”'),
('«نَحْنُ نَبِيعُ أَنْيَابَهَا، فَهِيَ عَاجٌ غَالٍ.»','“Biz dişlerini satarız; onlar pahalı fildişidir.”'),
('«فَكُنْتُ أَرْمِي كُلَّ يَوْمٍ، وَأَقْتُلُ فِيلًا، وَأُخْبِرُ سَيِّدِي.»','“Her gün ok atıyor, bir fil öldürüyor ve efendime haber veriyordum.”'),
('«وَبَقِيتُ عَلَى ذَلِكَ شَهْرَيْنِ.»','“İki ay böyle kaldım.”'),
('«لَكِنَّ قَلْبِي كَانَ حَزِينًا، فَالْفِيَلَةُ مَخْلُوقَاتٌ عَاقِلَةٌ.»','“Ama kalbim üzgündü; çünkü filler akıllı yaratıklardır.”')]),
('مَقْبَرَةُ الْفِيَلَةِ','Fillerin mezarlığı',[
('«وَفِي يَوْمٍ جَاءَتِ الْفِيَلَةُ كُلُّهَا، وَوَقَفَتْ حَوْلَ شَجَرَتِي.»','“Bir gün bütün filler geldi ve ağacımın etrafında durdu.”'),
('«فَخِفْتُ خَوْفًا شَدِيدًا، وَسَقَطَ الْقَوْسُ مِنْ يَدِي.»','“Çok korktum ve yay elimden düştü.”'),
('«فَلَفَّ أَكْبَرُ فِيلٍ خُرْطُومَهُ حَوْلَ الشَّجَرَةِ، وَقَلَعَهَا.»','“En büyük fil hortumunu ağaca doladı ve onu söktü.”'),
('«ثُمَّ حَمَلَنِي عَلَى ظَهْرِهِ، وَمَشَى بِي بَعِيدًا.»','“Sonra beni sırtına aldı ve beni uzağa götürdü.”'),
('«وَوَضَعَنِي فِي وَادٍ وَاسِعٍ، ثُمَّ ذَهَبَ مَعَ الْفِيَلَةِ.»','“Beni geniş bir vadiye bıraktı, sonra fillerle birlikte gitti.”'),
('«نَظَرْتُ، فَإِذَا الْوَادِي مَمْلُوءٌ بِعِظَامِ الْفِيَلَةِ وَأَنْيَابِهَا!»','“Baktım; bir de ne göreyim, vadi fil kemikleri ve dişleriyle dolu!”'),
('«فَفَهِمْتُ: هَذِهِ مَقْبَرَتُهَا. كَأَنَّهَا تَقُولُ لِي: خُذْ هَذَا، وَاتْرُكْنَا.»','“Anladım: Burası onların mezarlığı. Sanki bana diyorlardı: Bunu al ve bizi bırak.”')]),
('الْحُرِّيَّةُ','Özgürlük',[
('«رَجَعْتُ إِلَى سَيِّدِي، وَأَخْبَرْتُهُ بِالْوَادِي.»','“Efendime döndüm ve ona vadiyi haber verdim.”'),
('«فَذَهَبْنَا مَعًا، وَحَمَلْنَا مِنَ الْعَاجِ مَا لَا يُحْصَى.»','“Birlikte gittik ve sayısız fildişi taşıdık.”'),
('«فَفَرِحَ سَيِّدِي، وَقَالَ: أَنْتَ حُرٌّ لِوَجْهِ اللّٰهِ.»','“Efendim sevindi ve dedi ki: Allah rızası için hürsün.”'),
('«لَقَدْ أَغْنَيْتَنَا، وَأَنْقَذْتَ الْفِيَلَةَ مِنَ الْقَتْلِ.»','“Bizi zengin ettin ve filleri öldürülmekten kurtardın.”'),
('«ثُمَّ أَعْطَانِي نَصِيبًا كَبِيرًا مِنَ الْعَاجِ.»','“Sonra bana fildişinden büyük bir pay verdi.”'),
('«وَأَرْسَلَنِي فِي سَفِينَةٍ مَعَ تُجَّارٍ أُمَنَاءَ.»','“Beni güvenilir tüccarlarla bir gemiyle gönderdi.”'),
('«فَبِعْتُ الْعَاجَ فِي الطَّرِيقِ، وَاشْتَرَيْتُ هَدَايَا لِأَهْلِي.»','“Fildişini yolda sattım ve ailem için hediyeler aldım.”')]),
('الْعَوْدَةُ الْأَخِيرَةُ','Son dönüş',[
('«وَصَلْتُ إِلَى بَغْدَادَ بَعْدَ سَبْعٍ وَعِشْرِينَ سَنَةً مِنْ أَوَّلِ سَفَرٍ.»','“İlk yolculuktan yirmi yedi yıl sonra Bağdat’a vardım.”'),
('«فَذَهَبْتُ إِلَى الْخَلِيفَةِ، وَحَكَيْتُ لَهُ مَا حَدَثَ.»','“Halifeye gittim ve olanları ona anlattım.”'),
('«فَتَعَجَّبَ، وَأَمَرَ أَنْ تُكْتَبَ رِحْلَاتِي فِي كِتَابٍ.»','“Şaştı ve yolculuklarımın bir kitaba yazılmasını emretti.”'),
('«ثُمَّ قُلْتُ: يَا رَبِّ، تُبْتُ مِنَ السَّفَرِ، وَالْحَمْدُ لِلّٰهِ عَلَى السَّلَامَةِ.»','“Sonra dedim ki: Rabbim, yolculuktan tövbe ettim; selamet için hamd Allah’adır.”'),
('«وَمُنْذُ ذَلِكَ الْيَوْمِ وَأَنَا فِي بَيْتِي، أُطْعِمُ الْجَائِعَ، وَأُكْرِمُ الضَّيْفَ.»','“O günden beri evimdeyim; açı doyuruyor, misafire ikram ediyorum.”')]),
('السِّنْدِبَادُ وَالسِّنْدِبَادُ','Sindbad ile Sindbad',[
('ثُمَّ الْتَفَتَ السِّنْدِبَادُ الْبَحْرِيُّ إِلَى الْحَمَّالِ.','Sonra Denizci Sindbad hamala döndü.'),
('قَالَ: «يَا أَخِي، أَتَذْكُرُ مَا قُلْتَ عِنْدَ بَابِي فِي أَوَّلِ يَوْمٍ؟»','Dedi ki: “Kardeşim, ilk gün kapımın önünde ne dediğini hatırlıyor musun?”'),
('«قُلْتَ: هَذَا يَتَنَعَّمُ وَأَنَا أَتْعَبُ. فَهَلْ رَأَيْتَ الْآنَ كَيْفَ تَعِبْتُ؟»','“Dedin ki: Bu nimet içinde, ben ise yoruluyorum. Şimdi nasıl yorulduğumu gördün mü?”'),
('قَالَ الْحَمَّالُ: «رَأَيْتُ، وَاللّٰهِ. أَنْتَ تَسْتَحِقُّ مَا أَعْطَاكَ اللّٰهُ.»','Hamal dedi ki: “Vallahi gördüm. Sen Allah’ın sana verdiğini hak ediyorsun.”'),
('«وَأَنَا تَعَلَّمْتُ أَلَّا أَحْسُدَ أَحَدًا، فَلِكُلِّ إِنْسَانٍ قِصَّةٌ لَا نَعْرِفُهَا.»','“Ben de kimseyi kıskanmamayı öğrendim; çünkü her insanın bilmediğimiz bir hikâyesi var.”'),
('فَضَحِكَ السِّنْدِبَادُ، وَقَالَ: «كُنْ صَدِيقِي، وَتَعَالَ إِلَيَّ كُلَّ يَوْمٍ.»','Sindbad güldü ve dedi ki: “Dostum ol ve her gün bana gel.”'),
('فَصَارَ الْحَمَّالُ صَدِيقَهُ، وَعَاشَا فِي مَحَبَّةٍ وَسُرُورٍ.','Hamal onun dostu oldu; ikisi sevgi ve sevinç içinde yaşadılar.'),
('وَهُنَا تَنْتَهِي رِحْلَاتُ السِّنْدِبَادِ السَّبْعُ.','Ve burada Sindbad’ın yedi yolculuğu sona erer.')]),
]
